INSERT INTO `research` (`research_id`, `project_name`, `lead_scientist`, `start_date`, `status`, `summary`, `created_at`) VALUES (89, 'Trehalose-Liposome Delivery as a Non-Toxic Alternative to DMSO (Cohort 5)', 'Dr. Rajesh Sengupta', '2025-10-15', 'In Review', 'Engineering cryoprotectant formulations reducing post-thaw DMSO toxicity in pediatric autologous transplantations.', '2026-09-10 06:15:47.905438');
INSERT INTO `research` (`research_id`, `project_name`, `lead_scientist`, `start_date`, `status`, `summary`, `created_at`) VALUES (90, 'Cord Blood Regulatory T-Cells (Tregs) for Solid Organ Tolerance (Cohort 5)', 'Dr. Sanjay Verma', '2024-09-03', 'Ongoing', 'Preclinical evaluation of ex-vivo expanded cord blood Tregs to prevent allograft rejection in pediatric kidney transplant.', '2026-09-10 06:15:47.905438');
INSERT INTO `research` (`research_id`, `project_name`, `lead_scientist`, `start_date`, `status`, `summary`, `created_at`) VALUES (91, 'Optimization of Granulocyte-Colony Stimulating Factor Mobilization Schedules (Cohort 5)', 'Dr. Meera Joshi', '2025-02-22', 'Completed', 'Prospective comparative study of 4-day vs 5-day G-CSF dosing regimens on total CD34+ apheresis collection efficiency.', '2026-09-10 06:15:47.905438');
INSERT INTO `research` (`research_id`, `project_name`, `lead_scientist`, `start_date`, `status`, `summary`, `created_at`) VALUES (92, 'Spatial Transcriptomics of Bone Marrow Niches Post-Engraftment (Cohort 5)', 'Dr. Arvind Swaminathan', '2025-10-23', 'Active', 'Single-cell spatial profiling mapping donor cell reconstitution dynamics across osteoblast and vascular niches.', '2026-09-10 06:15:47.905438');
INSERT INTO `research` (`research_id`, `project_name`, `lead_scientist`, `start_date`, `status`, `summary`, `created_at`) VALUES (93, 'Mitochondrial Transfer from MSCs to Injured Endothelial Tissues (Cohort 5)', 'Dr. Rohan Bhattacharya', '2025-06-26', 'Ongoing', 'Investigating tunneling nanotube mediated organelle donation to reverse radiation-induced vascular damage.', '2026-09-10 06:15:47.905438');
INSERT INTO `research` (`research_id`, `project_name`, `lead_scientist`, `start_date`, `status`, `summary`, `created_at`) VALUES (94, 'Pre-Transplant NGS Chimerism Profiling for Minimal Residual Disease (Cohort 5)', 'Dr. Rajesh Sengupta', '2024-06-02', 'Ongoing', 'Developing ultra-sensitive duplex sequencing tracking donor chimerism down to 0.001% sensitivity.', '2026-09-10 06:15:47.905438');
