CREATE DATABASE IF NOT EXISTS stemcelldb;
USE stemcelldb;

-- Table: patients
DROP TABLE IF EXISTS audit_logs;
DROP TABLE IF EXISTS storage;
DROP TABLE IF EXISTS donors;
DROP TABLE IF EXISTS patients;
DROP TABLE IF EXISTS staff;
DROP TABLE IF EXISTS research;
DROP TABLE IF EXISTS inventory;

CREATE TABLE patients (
  patient_id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(150) NOT NULL,
  age INT,
  blood_group VARCHAR(10),
  contact VARCHAR(50),
  disease VARCHAR(255),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE donors (
  donor_id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(150) NOT NULL,
  age INT,
  blood_group VARCHAR(10),
  contact VARCHAR(50),
  donation_date DATE,
  notes TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  patient_id INT NULL,
  FOREIGN KEY (patient_id) REFERENCES patients(patient_id) ON DELETE SET NULL
);

CREATE TABLE storage (
  storage_id INT AUTO_INCREMENT PRIMARY KEY,
  storage_location VARCHAR(100),
  collected_date DATE,
  expiry_date DATE,
  units INT DEFAULT 1,
  donor_id INT NULL,
  FOREIGN KEY (donor_id) REFERENCES donors(donor_id) ON DELETE SET NULL
);

CREATE TABLE inventory (
  item_id INT AUTO_INCREMENT PRIMARY KEY,
  item_name VARCHAR(150) NOT NULL,
  quantity INT DEFAULT 0,
  unit VARCHAR(50),
  last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

CREATE TABLE staff (
  staff_id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  role VARCHAR(100),
  department VARCHAR(255),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE research (
  research_id INT AUTO_INCREMENT PRIMARY KEY,
  project_name VARCHAR(255) NOT NULL,
  lead_scientist VARCHAR(150),
  start_date DATE,
  status VARCHAR(50),
  summary TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE audit_logs (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  table_name VARCHAR(128) NOT NULL,
  operation VARCHAR(20) NOT NULL,
  record_id BIGINT NULL,
  changed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  changed_by VARCHAR(128) NULL,
  old_values TEXT NULL,
  new_values TEXT NULL
);

